-- =========================================================================
-- PropertyOS — Enable Row Level Security
-- Migration: enable_rls_policies
-- SCOPED TO SPRINT 1: only covers tables confirmed to exist in staging via
-- information_schema query (organizations, permissions, role_permissions,
-- roles, user_organization_roles, users). Re-run the information_schema
-- query and extend this file as later sprints migrate more domains.
--
-- Column names are PascalCase as generated by EF Core (not snake_case) —
-- every column reference below is double-quoted to match exactly. Table
-- names are lowercase/snake_case and do not need quoting.
--
-- Confirmed: users can belong to MULTIPLE organizations (no direct
-- OrganizationId column on users — membership lives in
-- user_organization_roles). Policies on users/role_permissions use an
-- EXISTS join rather than a direct column comparison as a result.
--
-- Session variable assumed: app.current_org_id, set per-request by the
-- API before running queries, e.g.:
--   SET LOCAL app.current_org_id = '<org-uuid>';
-- =========================================================================

-- -------------------------------------------------------------------------
-- organizations — this table IS the tenant root, so it's scoped by its own
-- "Id", not an OrganizationId column. Writes are intentionally NOT opened
-- up here (org creation / hard delete should go through the API using a
-- service-role connection, not raw end-user RLS-permitted writes).
-- -------------------------------------------------------------------------

ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;

CREATE POLICY org_isolation_select ON organizations FOR SELECT
  USING ("Id" = current_setting('app.current_org_id', true)::uuid);

CREATE POLICY org_isolation_update ON organizations FOR UPDATE
  USING ("Id" = current_setting('app.current_org_id', true)::uuid)
  WITH CHECK ("Id" = current_setting('app.current_org_id', true)::uuid);

-- -------------------------------------------------------------------------
-- permissions — global catalog, not org-scoped. Read-only for everyone;
-- new permission codes are a deploy-time/admin concern via service role.
-- -------------------------------------------------------------------------

ALTER TABLE permissions ENABLE ROW LEVEL SECURITY;

CREATE POLICY catalog_read_only ON permissions FOR SELECT USING (true);

-- -------------------------------------------------------------------------
-- roles — "OrganizationId" is nullable (NULL = system-defined global role,
-- visible to everyone; non-null = that org's own custom role).
-- -------------------------------------------------------------------------

ALTER TABLE roles ENABLE ROW LEVEL SECURITY;

CREATE POLICY org_isolation_select ON roles FOR SELECT
  USING (
    "OrganizationId" = current_setting('app.current_org_id', true)::uuid
    OR "OrganizationId" IS NULL
  );

CREATE POLICY org_isolation_write ON roles FOR INSERT
  WITH CHECK ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

CREATE POLICY org_isolation_update ON roles FOR UPDATE
  USING ("OrganizationId" = current_setting('app.current_org_id', true)::uuid)
  WITH CHECK ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

CREATE POLICY org_isolation_delete ON roles FOR DELETE
  USING ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

-- Note: these policies allow an org to CRUD only its own custom roles.
-- System roles (OrganizationId IS NULL) are readable by all but not
-- writable by any org session — only a service role should modify them.

-- -------------------------------------------------------------------------
-- role_permissions — no OrganizationId column; scoped via a join to roles.
-- -------------------------------------------------------------------------

ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;

CREATE POLICY org_isolation_select ON role_permissions FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM roles r
      WHERE r."Id" = role_permissions."RoleId"
        AND (r."OrganizationId" = current_setting('app.current_org_id', true)::uuid
             OR r."OrganizationId" IS NULL)
    )
  );

CREATE POLICY org_isolation_write ON role_permissions FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM roles r
      WHERE r."Id" = role_permissions."RoleId"
        AND r."OrganizationId" = current_setting('app.current_org_id', true)::uuid
    )
  );

CREATE POLICY org_isolation_delete ON role_permissions FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM roles r
      WHERE r."Id" = role_permissions."RoleId"
        AND r."OrganizationId" = current_setting('app.current_org_id', true)::uuid
    )
  );

-- Note: deliberately no UPDATE policy — role_permissions is a pure junction
-- row (role <-> permission); changing an assignment should be a delete +
-- insert, not an in-place update.

-- -------------------------------------------------------------------------
-- user_organization_roles — has a direct OrganizationId column.
-- -------------------------------------------------------------------------

ALTER TABLE user_organization_roles ENABLE ROW LEVEL SECURITY;

CREATE POLICY org_isolation_select ON user_organization_roles FOR SELECT
  USING ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

CREATE POLICY org_isolation_write ON user_organization_roles FOR INSERT
  WITH CHECK ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

CREATE POLICY org_isolation_delete ON user_organization_roles FOR DELETE
  USING ("OrganizationId" = current_setting('app.current_org_id', true)::uuid);

-- Note: no UPDATE policy for the same reason as role_permissions — a role
-- reassignment should be a delete + insert, not mutating an existing row.

-- -------------------------------------------------------------------------
-- users — no OrganizationId column (confirmed: a user can belong to
-- multiple orgs). Visibility is scoped via a join to
-- user_organization_roles instead of a direct column comparison.
-- -------------------------------------------------------------------------

ALTER TABLE users ENABLE ROW LEVEL SECURITY;

CREATE POLICY org_isolation_select ON users FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM user_organization_roles uor
      WHERE uor."UserId" = users."Id"
        AND uor."OrganizationId" = current_setting('app.current_org_id', true)::uuid
    )
  );

-- Deliberately NO insert/update/delete policy on users for the
-- authenticated role yet:
--   - User creation happens via Supabase Auth + a service-role write
--     (signup flow), not an org-scoped end-user insert.
--   - Editing another user's profile (as an org admin) is a privileged
--     action that should go through a dedicated API endpoint using a
--     service-role connection with its own authorization check — not a
--     blanket RLS policy that would let any org member edit any other
--     member's record.
--   - "Edit my own profile" can be added once you confirm what session
--     variable identifies the calling user (e.g. app.current_user_id):
--
--     CREATE POLICY self_update ON users FOR UPDATE
--       USING ("Id" = current_setting('app.current_user_id', true)::uuid)
--       WITH CHECK ("Id" = current_setting('app.current_user_id', true)::uuid);